// Every colour of the default palette is a CSS variable (src/theme.css, generated by scripts/gen-theme.cjs): the light values on :root, the same
// scale reversed under .dark - so the dark theme is one class on <html> and no component needs its own dark: variants.
import colors from 'tailwindcss/colors'

const FAMILIES = ['slate', 'gray', 'zinc', 'neutral', 'stone', 'red', 'orange', 'amber', 'yellow', 'lime', 'green', 'emerald', 'teal', 'cyan', 'sky', 'blue', 'indigo', 'violet', 'purple', 'fuchsia', 'pink', 'rose']
const SHADES = [50, 100, 200, 300, 400, 500, 600, 700, 800, 900, 950]
const themed = Object.fromEntries(FAMILIES.map(f => [f, Object.fromEntries(SHADES.map(s => [s, `rgb(var(--c-${f}-${s}) / <alpha-value>)`]))]))

/** @type {import('tailwindcss').Config} */
export default {
  darkMode: 'class',
  content: ['./index.html', './src/**/*.{js,ts,jsx,tsx}'],
  theme: {
    extend: {
      colors: {
        ...themed,
        white: 'rgb(var(--c-white) / <alpha-value>)',
        brand: {
          50: '#eef2ff',
          100: '#e0e7ff',
          500: '#6366f1',
          600: '#4f46e5',
          700: '#4338ca',
          900: '#1e1b4b',
        },
      },
    },
  },
  plugins: [],
}
